using System.Collections.Concurrent;
using System.Security.Cryptography;
using System.Text.Json;
using System.Text.Json.Nodes;
using Astronomy.MediaFactory.Core.DocumentaryBlueprint;

namespace Astronomy.MediaFactory.Infrastructure.DocumentaryBlueprint;

public sealed class Phase4ArtifactSerializer:IPhase4ArtifactSerializer
{
    private static readonly JsonSerializerOptions Options=new(JsonSerializerDefaults.Web){WriteIndented=true};
    public byte[] Serialize<T>(T value)=>JsonSerializer.SerializeToUtf8Bytes(value,Options);
    public T Deserialize<T>(byte[] bytes)=>JsonSerializer.Deserialize<T>(bytes,Options) ?? throw new JsonException($"Could not deserialize {typeof(T).Name}.");
    public string SemanticChecksum<T>(T value,Func<T,T> clearChecksum)=>Convert.ToHexString(SHA256.HashData(JsonSerializer.SerializeToUtf8Bytes(clearChecksum(value),new JsonSerializerOptions(JsonSerializerDefaults.Web)))).ToLowerInvariant();
}
public sealed class Phase4FileSystem:IPhase4FileSystem
{
    public async Task WriteAsync(string path,byte[] bytes,CancellationToken token){Directory.CreateDirectory(Path.GetDirectoryName(path)!);await File.WriteAllBytesAsync(path,bytes,token);}
    public byte[] Read(string path)=>File.ReadAllBytes(path);
    public string Sha256(byte[] bytes)=>Convert.ToHexString(SHA256.HashData(bytes)).ToLowerInvariant();
}
public sealed class Phase4ExecutionLock:IPhase4ExecutionLock
{
    private static readonly ConcurrentDictionary<string,SemaphoreSlim> Locks=new(StringComparer.OrdinalIgnoreCase);
    public async ValueTask<IAsyncDisposable> AcquireAsync(string root,string id,CancellationToken token){var key=Path.GetFullPath(root)+"|"+id;var gate=Locks.GetOrAdd(key,_=>new(1,1));await gate.WaitAsync(token);try{Directory.CreateDirectory(Path.Combine(root,".locks"));var stream=new FileStream(Path.Combine(root,".locks",Safe(id)+".phase-04.lock"),FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None);return new Releaser(gate,stream);}catch{gate.Release();throw;}static string Safe(string x)=>string.Concat(x.Select(c=>Path.GetInvalidFileNameChars().Contains(c)?'_':c));}
    private sealed class Releaser(SemaphoreSlim gate,FileStream stream):IAsyncDisposable{public ValueTask DisposeAsync(){stream.Dispose();gate.Release();return ValueTask.CompletedTask;}}
}
public sealed class Phase4RecoveryService:IPhase4RecoveryService
{
    public Task<bool> RecoverAsync(string root,CancellationToken token){var recovered=false;foreach(var path in Directory.Exists(root)?Directory.EnumerateDirectories(root,".*.phase-04.tmp"):[]){token.ThrowIfCancellationRequested();var metadata=Path.Combine(path,"transaction.json");if(!File.Exists(metadata))continue;Phase4TransactionRecord? tx;try{tx=JsonSerializer.Deserialize<Phase4TransactionRecord>(File.ReadAllBytes(metadata),new JsonSerializerOptions(JsonSerializerDefaults.Web));}catch{continue;}if(tx is null||DateTimeOffset.UtcNow-tx.CreatedUtc<TimeSpan.FromHours(1))continue;Directory.Delete(path,true);recovered=true;}foreach(var backup in Directory.Exists(root)?Directory.EnumerateDirectories(root,".*.phase-04.backup"):[]){token.ThrowIfCancellationRequested();var metadata=Path.Combine(backup,"transaction.json");if(!File.Exists(metadata))continue;var target=Path.Combine(root,"04-blueprint");RestoreDirectory(Path.Combine(backup,"04-blueprint"),target);Restore(Path.Combine(backup,"phase-manifest.json"),Path.Combine(root,"phase-manifest.json"));Restore(Path.Combine(backup,"phase-04-validation.json"),Path.Combine(root,"validation","phase-04-validation.json"));Restore(Path.Combine(backup,"story-graph.json"),Path.Combine(root,"compatibility","story-graph.json"));Directory.Delete(backup,true);recovered=true;}return Task.FromResult(recovered);static void Restore(string source,string target){if(!File.Exists(source))return;Directory.CreateDirectory(Path.GetDirectoryName(target)!);File.Move(source,target,true);}static void RestoreDirectory(string source,string target){if(!Directory.Exists(source))return;if(Directory.Exists(target))Directory.Delete(target,true);Directory.Move(source,target);}}
}
public sealed class Phase4ManifestUpdater(IPhase4ArtifactSerializer serializer):IPhase4ManifestUpdater
{
    public byte[] Merge(byte[]? existing,IReadOnlyList<Phase4ArtifactEntry> entries){JsonObject root;if(existing is {Length:>0})root=JsonNode.Parse(existing)?.AsObject()??new();else root=new JsonObject{{"schemaVersion","phase-manifest.v1"}};root["phase4Artifacts"]=JsonSerializer.SerializeToNode(entries.OrderBy(x=>x.RelativePath,StringComparer.Ordinal),new JsonSerializerOptions(JsonSerializerDefaults.Web));return serializer.Serialize(root);}
}
public sealed class Phase4PublishedAuthorityValidator(IPhase4ArtifactSerializer serializer):IPhase4PublishedAuthorityValidator
{
    public Task<IReadOnlyList<Phase4PublicationDiagnostic>> ValidateAsync(string dir,DocumentaryBlueprintAggregate expected,CancellationToken token)
    {var errors=new List<Phase4PublicationDiagnostic>();try{var allowed=new HashSet<string>(new[]{"documentary-blueprint.json","documentary-blueprint.long.json","documentary-blueprint.short.json","knowledge-selection.json","long-scene-index.json","short-scene-index.json","blueprint-build-report.json"},StringComparer.Ordinal);if(!Directory.Exists(dir))throw new DirectoryNotFoundException(dir);foreach(var file in Directory.EnumerateFiles(dir))if(!allowed.Contains(Path.GetFileName(file)))errors.Add(new(Phase4PublicationReasonCodes.TemporaryValidationFailed,"Unknown staged file.",file));foreach(var name in allowed)if(!File.Exists(Path.Combine(dir,name)))errors.Add(new(Phase4PublicationReasonCodes.TemporaryValidationFailed,$"Required artifact is missing: {name}"));if(errors.Count>0)return Task.FromResult<IReadOnlyList<Phase4PublicationDiagnostic>>(errors);var aggregate=Read<DocumentaryBlueprintAggregate>("documentary-blueprint.json");var lng=Read<DocumentaryBlueprintVariantArtifact>("documentary-blueprint.long.json");var sh=Read<DocumentaryBlueprintVariantArtifact>("documentary-blueprint.short.json");var knowledge=Read<DocumentaryBlueprintKnowledgeSelectionArtifact>("knowledge-selection.json");var li=Read<Phase4SceneIndex>("long-scene-index.json");var si=Read<Phase4SceneIndex>("short-scene-index.json");var report=Read<Phase4BlueprintBuildReport>("blueprint-build-report.json");if(!DocumentaryBlueprintProjectionChecksum.HasValidAggregateChecksum(aggregate)||aggregate.DeterministicChecksum!=expected.DeterministicChecksum)Fail("Aggregate checksum mismatch.");ValidateVariant(lng,aggregate.LongVariant,"Long");ValidateVariant(sh,aggregate.ShortVariant,"Short");ValidateKnowledge(knowledge,aggregate);ValidateIndex(li,aggregate.LongVariant,"Long");ValidateIndex(si,aggregate.ShortVariant,"Short");if(report.AggregateChecksum!=aggregate.DeterministicChecksum||report.LongVariantChecksum!=lng.DeterministicChecksum||report.ShortVariantChecksum!=sh.DeterministicChecksum||report.LongSceneCount!=lng.Blueprint.Scenes.Count||report.ShortSceneCount!=sh.Blueprint.Scenes.Count||!report.ArtifactInventory.OrderBy(x=>x).SequenceEqual(allowed.OrderBy(x=>x)))Fail("Build report drift detected.");Check(knowledge,knowledge.DeterministicChecksum,x=>x with{DeterministicChecksum=""});Check(li,li.DeterministicChecksum,x=>x with{DeterministicChecksum=""});Check(si,si.DeterministicChecksum,x=>x with{DeterministicChecksum=""});Check(report,report.DeterministicChecksum,x=>x with{DeterministicChecksum=""});void ValidateVariant(DocumentaryBlueprintVariantArtifact actual,DocumentaryBlueprintVariantArtifact embedded,string variant){if(!DocumentaryBlueprintProjectionChecksum.HasValidVariantChecksum(actual)||!serializer.Serialize(actual).SequenceEqual(serializer.Serialize(embedded)))Fail($"{variant} projection is not exactly the embedded variant.");}void ValidateKnowledge(DocumentaryBlueprintKnowledgeSelectionArtifact artifact,DocumentaryBlueprintAggregate a){var expectedSelections=a.LongVariant.SceneTraceability.Concat(a.ShortVariant.SceneTraceability).SelectMany(x=>x.KnowledgeSelections).Select(x=>x.KnowledgeSelectionId).OrderBy(x=>x).ToArray();var actual=artifact.LongSelections.Concat(artifact.ShortSelections).Select(x=>x.KnowledgeSelectionId).OrderBy(x=>x).ToArray();if(!actual.SequenceEqual(expectedSelections)||artifact.LongSelections.Concat(artifact.ShortSelections).Any(x=>x.EvidenceStatus==QuestionEvidenceStatus.EditorialOnly))Fail("Knowledge selection drift or editorial-only knowledge detected.");}void ValidateIndex(Phase4SceneIndex index,DocumentaryBlueprintVariantArtifact variant,string name){var scenes=variant.Blueprint.Scenes.OrderBy(x=>x.SceneNumber).ToArray();if(index.Variant!=name||index.Scenes.Count!=scenes.Length||index.Scenes.Select(x=>x.SceneNumber).Where((x,i)=>x!=i+1).Any())Fail($"{name} scene index count/order drift.");for(var i=0;i<Math.Min(scenes.Length,index.Scenes.Count);i++)if(index.Scenes[i].SceneId!=scenes[i].SceneId||index.Scenes[i].TargetDurationSeconds!=scenes[i].EstimatedDurationSeconds||index.Scenes[i].TransitionIntent!=scenes[i].Transition.TransitionIntent)Fail($"{name} scene index drift.");}T Read<T>(string name)=>serializer.Deserialize<T>(File.ReadAllBytes(Path.Combine(dir,name)));void Check<T>(T value,string checksum,Func<T,T> clear){if(serializer.SemanticChecksum(value,clear)!=checksum)Fail($"{typeof(T).Name} deterministic checksum mismatch.");}void Fail(string message)=>errors.Add(new(Phase4PublicationReasonCodes.TemporaryValidationFailed,message));}catch(Exception ex){errors.Add(new(Phase4PublicationReasonCodes.TemporaryValidationFailed,ex.Message));}return Task.FromResult<IReadOnlyList<Phase4PublicationDiagnostic>>(errors);}
}

public sealed class Phase4CommittedStateValidator(IPhase4PublishedAuthorityValidator physical,IPhase4ArtifactSerializer serializer):IPhase4CommittedStateValidator
{public async Task<IReadOnlyList<Phase4PublicationDiagnostic>> ValidateAsync(string root,DocumentaryBlueprintAggregate expected,CancellationToken token){var errors=(await physical.ValidateAsync(Path.Combine(root,"04-blueprint"),expected,token)).ToList();try{var manifest=JsonNode.Parse(File.ReadAllBytes(Path.Combine(root,"phase-manifest.json")))?.AsObject()??throw new JsonException("Manifest root missing.");var entries=manifest["phase4Artifacts"]?.Deserialize<Phase4ArtifactEntry[]>(new JsonSerializerOptions(JsonSerializerDefaults.Web))??[];if(entries.Length!=7)throw new JsonException("Manifest must contain seven Phase 4 entries.");foreach(var entry in entries){var path=Path.Combine(root,entry.RelativePath.Replace('/',Path.DirectorySeparatorChar));if(!File.Exists(path)||Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(path))).ToLowerInvariant()!=entry.PhysicalSha256)throw new JsonException($"Manifest mismatch: {entry.RelativePath}");}var validation=serializer.Deserialize<Phase4ValidationRecord>(File.ReadAllBytes(Path.Combine(root,"validation","phase-04-validation.json")));var actual=serializer.SemanticChecksum(validation,x=>x with{DeterministicChecksum=""});if(!validation.PublicationCommitted||validation.ValidationStatus!="Valid"||validation.AggregateChecksum!=expected.DeterministicChecksum||validation.DeterministicChecksum!=actual)throw new JsonException("Success validation is not a valid commit marker.");}catch(Exception ex){errors.Add(new(Phase4PublicationReasonCodes.PostCommitValidationFailed,ex.Message));}return errors;}}
